//! Fixtures generated by the unmodified historical codecs at
//! iobewi_old@345378ed1ae11a4814c32ee513f20438291cfba7.
//! The 2-byte LE length prefix is test framing, not an on-flash format.
use iobewi_firmware_update::compat::{otm1, otm2};

fn records(bytes: &[u8]) -> impl Iterator<Item = &[u8]> {
    let mut remaining = bytes;
    std::iter::from_fn(move || {
        if remaining.is_empty() {
            return None;
        }
        let len = u16::from_le_bytes(remaining[..2].try_into().unwrap()) as usize;
        let record = &remaining[2..2 + len];
        remaining = &remaining[2 + len..];
        Some(record)
    })
}

#[test]
fn otm1_preserves_all_historical_stage_size_and_identity_vectors() {
    let mut fixtures = records(include_bytes!("fixtures/otm1.bin"));
    for stage in [
        otm1::Stage::None,
        otm1::Stage::Written,
        otm1::Stage::Activating,
    ] {
        for size in [0, 1, 4096, u32::MAX] {
            for deployment in ["deployment-1", "déploiement-2"] {
                let metadata = otm1::Metadata {
                    staged: otm1::Staged {
                        stage,
                        slot: "ota_1".into(),
                        digest: "sha256:012345".into(),
                        deployment_id: deployment.into(),
                        size,
                    },
                    active_digest: "sha256:987654".into(),
                    active_deployment_id: "previous".into(),
                };
                let expected = fixtures.next().unwrap();
                assert_eq!(metadata.encode().unwrap(), expected);
                assert_eq!(
                    otm1::Metadata::decode(expected).unwrap().encode().unwrap(),
                    expected
                );
            }
        }
    }
    assert!(fixtures.next().is_none());
}

#[test]
fn otm2_preserves_all_historical_state_and_sequence_vectors() {
    use otm2::{Record, RuntimeApi, Side, SlotMeta, State};
    let mut fixtures = records(include_bytes!("fixtures/otm2.bin"));
    for seq in [0, 1, 7, u32::MAX] {
        for state in [
            State::Empty,
            State::Valid,
            State::Staged,
            State::Activating,
            State::PendingConfirmation,
            State::RollingBack,
        ] {
            let mut record = Record::empty(seq);
            record.state = state;
            record.meta[0] = SlotMeta::new(
                "old-system",
                "1.2.3",
                [0x11; 32],
                4096,
                RuntimeApi::new(1, 2),
            )
            .unwrap();
            record.meta[1] = SlotMeta::new(
                "new-system",
                "4.5.6",
                [0x22; 32],
                8192,
                RuntimeApi::new(1, 3),
            )
            .unwrap();
            match state {
                State::Empty => record.meta = [SlotMeta::EMPTY; 2],
                State::Valid => record.active = Some(Side::A),
                State::Staged | State::Activating => {
                    record.active = Some(Side::A);
                    record.candidate = Some(Side::B);
                }
                State::PendingConfirmation | State::RollingBack => {
                    record.active = Some(Side::B);
                    record.previous_valid = Some(Side::A);
                }
            }
            assert_eq!(record.encode().as_slice(), fixtures.next().unwrap());
        }
    }
    assert!(fixtures.next().is_none());
}
